import{_ as s,y as r,a as n,o as i,a2 as o,D as a,g as l}from"./chunks/framework.DCcmcJcL.js";const y=JSON.parse('{"title":"Appearance","description":"","frontmatter":{},"headers":[],"relativePath":"appearance/themes.md","filePath":"appearance/themes.md","lastUpdated":1789330126000}'),h={name:"appearance/themes.md"};function d(c,e,p,g,u,m){const t=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=o('<h1 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h1><p>The appearance of your storefront defines its look and feel, and is a key factor in the first impression it makes on a visitor.</p><p>Appearance has its own area in the admin, separate from Settings. It holds two things: the <strong>themes</strong> available to your store, and the <strong>sections</strong> a theme&#39;s storefront is built from.</p><h2 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h2><p>Go to <strong>Appearance &gt;&gt; Themes</strong> to see every theme, grouped so you can tell at a glance which are ready to use:</p><ul><li><strong>My Themes</strong> — themes installed on your store. Each shows whether it is active, and on which channels.</li><li><strong>Buy Themes</strong> — themes available from the marketplace, with links to preview or purchase them.</li></ul>',6)),a(t,{src:"/images/appearance/themes.png",alt:"Themes"}),e[1]||(e[1]=o('<p>From an installed theme you can:</p><ul><li><strong>Customize</strong> — open the section editor for that theme.</li><li><strong>Activate</strong> — apply the theme to one or more channels. Before it is applied, you are shown what the change affects.</li></ul><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><p>A section is one block of the storefront — a product carousel, a banner slider, a footer, and so on. Sections belong to a <strong>theme</strong> and a <strong>channel</strong>, so the same theme customised on two channels keeps two independent sets.</p><p>Open <strong>Appearance &gt;&gt; Themes</strong>, then <strong>Customize</strong> on the theme you want to edit.</p><h3 id="the-editor" tabindex="-1">The editor <a class="header-anchor" href="#the-editor" aria-label="Permalink to &quot;The editor&quot;">​</a></h3><p>The editor shows the list of sections on the left and a live storefront preview on the right. Selecting a section opens its fields; the preview updates as you edit, so you can see the result before anyone else does.</p><ul><li><strong>Reorder</strong> — drag a section by its handle to change where it appears.</li><li><strong>Switch on or off</strong> — use the toggle on the row.</li><li><strong>Duplicate</strong> or <strong>Delete</strong> — from the row&#39;s menu. Duplicating copies the section with everything configured in it, which is the quickest way to build a second carousel that differs in one filter. The copy is placed just below the original, named with <strong>Copy</strong> at the end, and starts switched off and unsaved until you publish it. Deleting asks you to confirm and cannot be undone — to take a section off the storefront and keep it, switch it off instead.</li><li><strong>Change locale or channel</strong> — from the selectors at the top, when your store has more than one. Each combination is edited separately.</li><li><strong>Change device</strong> — preview the storefront at desktop, tablet or mobile width.</li></ul>',8)),a(t,{src:"/images/appearance/section-editor.png",alt:"Section Editor"}),e[2]||(e[2]=l("p",null,"The footer links section is pinned to the bottom of the page, so it has no drag handle and cannot be duplicated. Everything else can be moved freely.",-1)),a(t,{src:"/images/appearance/section-actions.png",alt:"Duplicate and Delete on a section row"}),e[3]||(e[3]=o('<h3 id="nothing-goes-live-until-you-publish" tabindex="-1">Nothing goes live until you publish <a class="header-anchor" href="#nothing-goes-live-until-you-publish" aria-label="Permalink to &quot;Nothing goes live until you publish&quot;">​</a></h3><p>Every change is held as an <strong>unsaved change</strong> until you publish it. This applies to everything: editing content, switching a section on or off, and reordering.</p><p>The header shows how many sections are holding unsaved changes, and each affected row is marked. From there you can:</p><ul><li><strong>Publish</strong> — send the changes to the storefront.</li><li><strong>Discard</strong> — throw them away and return to what is currently live.</li></ul><p>A newly created section is switched off and counts as unsaved, so an empty section is never shown to shoppers before it has been built.</p><h3 id="creating-a-section" tabindex="-1">Creating a section <a class="header-anchor" href="#creating-a-section" aria-label="Permalink to &quot;Creating a section&quot;">​</a></h3><ol><li>In the editor, click the <strong>+</strong> button beside the section list.</li><li>Choose the <strong>Type</strong> and enter a <strong>Name</strong>.</li><li>Click <strong>Save Section</strong>.</li></ol>',7)),a(t,{src:"/images/appearance/create-section.png",alt:"Create Section"}),e[4]||(e[4]=o('<ol start="4"><li>The section is added, switched off, and opened for editing. Fill in its fields.</li><li>Click <strong>Publish</strong> when you are ready for it to appear.</li></ol><h2 id="section-types" tabindex="-1">Section types <a class="header-anchor" href="#section-types" aria-label="Permalink to &quot;Section types&quot;">​</a></h2><h3 id="product-carousel" tabindex="-1">Product Carousel <a class="header-anchor" href="#product-carousel" aria-label="Permalink to &quot;Product Carousel&quot;">​</a></h3><p>A scrollable strip of products, used for the collections on your home page.</p><p><strong>Title:</strong> The heading shown above the carousel.</p><p><strong>Filters:</strong> Which products appear, and in what order. Click <strong>Add Filter</strong>, then choose the filter and its value:</p><ul><li><strong>Sort</strong> — the order products are shown in, using the same sort options your storefront listing offers.</li><li><strong>Limit</strong> — how many products the strip holds.</li><li><strong>Category ID</strong> — restrict the strip to one category. Categories are listed by their full path, so two categories sharing a name can be told apart.</li><li><strong>Featured</strong> — set to <strong>Yes</strong> to show only featured products.</li><li><strong>New</strong> — set to <strong>Yes</strong> to show only products marked as new.</li></ul><p>Once every available filter has been added, the editor says so rather than offering an empty row. To drop a filter, use the bin beside it.</p>',8)),a(t,{src:"/images/appearance/product-carousel.png",alt:"Product Carousel section fields"}),e[5]||(e[5]=o('<h3 id="category-carousel" tabindex="-1">Category Carousel <a class="header-anchor" href="#category-carousel" aria-label="Permalink to &quot;Category Carousel&quot;">​</a></h3><p>A scrollable strip of categories, so shoppers can jump straight into a department.</p><p><strong>Filters:</strong> Which categories appear, and in what order:</p><ul><li><strong>Sort</strong> — <strong>Asc</strong> or <strong>Desc</strong>.</li><li><strong>Limit</strong> — how many categories the strip holds.</li><li><strong>Parent ID</strong> — show the children of one or more chosen categories. Pick <strong>Root</strong> to show your top-level departments.</li></ul>',4)),a(t,{src:"/images/appearance/category-carousel.png",alt:"Category Carousel section fields"}),e[6]||(e[6]=o('<h3 id="image-carousel" tabindex="-1">Image Carousel <a class="header-anchor" href="#image-carousel" aria-label="Permalink to &quot;Image Carousel&quot;">​</a></h3><p>The banner slideshow at the top of your storefront. Click <strong>Add Slider</strong> to add a slide at a time, each with:</p><p><strong>Slider Image:</strong> The image itself. A resolution of <strong>1920 × 700</strong> is recommended, and JPEG, JPG, PNG and WEBP files are accepted.</p><p><strong>Image Title:</strong> The heading shown over the slide.</p><p><strong>Link:</strong> Where a shopper who clicks the slide is taken.</p><p>Slides play in the order they are listed, and you can drag them to change it.</p>',6)),a(t,{src:"/images/appearance/image-carousel.png",alt:"Image Carousel section fields"}),e[7]||(e[7]=o('<h3 id="static-content" tabindex="-1">Static Content <a class="header-anchor" href="#static-content" aria-label="Permalink to &quot;Static Content&quot;">​</a></h3><p>A free-form block of your own markup, for an announcement strip or a promotional band between two carousels.</p><p><strong>HTML:</strong> The content itself. Use <strong>Add Media</strong> to upload an image and drop it into the markup.</p><p><strong>CSS:</strong> Styles for the block. They are added to the whole page, not just this block, so give your markup its own class and start every rule with it, for example <code>.home-offer h1 { ... }</code>, or the styles will change other parts of the storefront too.</p><p>The HTML is cleaned before it is saved, so scripts, frames and forms are stripped — a block that relies on them will not behave as written.</p>',5)),a(t,{src:"/images/appearance/static-content.png",alt:"Static Content section fields"}),e[8]||(e[8]=o('<h3 id="footer-links" tabindex="-1">Footer Links <a class="header-anchor" href="#footer-links" aria-label="Permalink to &quot;Footer Links&quot;">​</a></h3><p>The link columns in your storefront footer. Click <strong>Add Column</strong> to add a column, then <strong>Add Link</strong> inside it, and give each link a <strong>Title</strong> — the wording a shopper reads — and a <strong>URL</strong>. Columns and the links inside them can be dragged into a different order. The default theme lays out as many columns as you add; a theme you install may limit the number.</p><p>A channel shows <strong>one footer links section</strong>, so once a channel has one, the type is no longer offered when you create a section.</p><h3 id="services-content" tabindex="-1">Services Content <a class="header-anchor" href="#services-content" aria-label="Permalink to &quot;Services Content&quot;">​</a></h3><p>The service promises shown across the storefront — free delivery, easy returns, and similar. Click <strong>Add Services</strong> to add an entry, each with:</p><p><strong>Service Icon:</strong> The name of the icon shown beside the promise, typed as text, such as <code>icon-truck</code> for delivery or <code>icon-support</code> for help.</p><p><strong>Title:</strong> The promise itself, kept to a few words.</p><p><strong>Description:</strong> A single line of supporting detail.</p>',8)),a(t,{src:"/images/appearance/services-content.png",alt:"Services Content section fields"}),e[9]||(e[9]=o('<p>Because this section and the footer are drawn on every page rather than just the home page, publishing a change to either refreshes the whole storefront cache.</p><h3 id="types-added-by-a-theme" tabindex="-1">Types added by a theme <a class="header-anchor" href="#types-added-by-a-theme" aria-label="Permalink to &quot;Types added by a theme&quot;">​</a></h3><p>The six types above are the ones every theme offers. A theme you install from the marketplace or have built for you can add types of its own, such as a testimonial slider or a brand strip. They appear in the same <strong>+</strong> list when that theme is being customised, with their own fields, and are edited and published exactly like the built-in types. If a type you expect is missing from the list, check that the theme it belongs to is the one you are customising.</p><h2 id="upgrading-from-an-earlier-version" tabindex="-1">Upgrading from an earlier version <a class="header-anchor" href="#upgrading-from-an-earlier-version" aria-label="Permalink to &quot;Upgrading from an earlier version&quot;">​</a></h2><p>If you used <strong>Settings &gt;&gt; Themes</strong> before, that screen has moved. Theme customizations are now sections, and they live under <strong>Appearance</strong>. Existing customizations are carried over automatically — you do not need to recreate them.</p>',5))])}const _=s(h,[["render",d]]);export{y as __pageData,_ as default};
